WITH valid AS (SELECT *, ROUND(amount, 2) AS amount_rounded, COALESCE(merchant, 'NONE') AS resolved_merchant FROM transactions WHERE txn_time > TO_DATE('2023-05-19') AND NOT is_flagged) SELECT id, account_id, txn_type, amount, is_flagged, amount_rounded, resolved_merchant, ROW_NUMBER() OVER (ORDER BY txn_time DESC, id) AS row_seq, SUM(amount) OVER (PARTITION BY txn_type ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount FROM valid
